'use strict';
// Админка: новости
/* Админка: новости */
const newsStTxt=n=>n.status==='Черновик'?'1/2 Черновик':n.off?'2/2 Опубликовано · снято':newsLive(n)?'2/2 Опубликовано':'2/2 Опубликовано · появится '+fmtD(n.date)+' в 09:00';
function newsLog(n,to,why){n.hist.push({at:nowStamp(),to,who:S.me,why});pdLog(`Новости: «${n.t}» — ${to}${why?' ('+why+')':''}`,'news')}
const NEWS_TPL='## Что нового\n- \n\n## Изменено\n- \n\n## Исправлено\n- \n\n## Где найти\n- \n\n## Что нужно сделать\n- \n';
// Слова, которых не должно быть в тексте для пользователей (пакет 16.11.2026, блок 4, пункт 4; по умолчанию)
const NEWS_TECH=[['прототип',/прототип/i],['миграция',/миграци/i],['стенд',/(^|[^а-яё])стенд/i],['поток',/(^|[^а-яё])поток/i],['PR',/(^|[^A-Za-z])PR([^A-Za-z]|$)/],['справочник платформы',/справочник(ах|ами|ов|и|е|а|у)? платформы/i]];
const newsTechWords=t=>NEWS_TECH.filter(([w,r])=>r.test(t||'')).map(([w])=>w);
const newsLoginDef=v=>v.pin||v.type==='Обновление'||v.type==='Нововведение';
// Пустые разделы шаблона (заголовок без пунктов) при сохранении убираются: у пользователя они не показываются
const mdTrim=md=>md.replace(/\r/g,'').split(/\n(?=##\s)/).filter(sec=>!/^##\s/.test(sec)||sec.split('\n').slice(1).some(l=>!/^\s*([-*]|\d+[.)])?\s*$/.test(l))).join('\n').replace(/\n{3,}/g,'\n\n').trim();
function newsEditDlg(n0){const isNew=!n0;const n=n0||{t:'',type:'Обновление',ver:'',date:TODAY,short:'',md:NEWS_TPL,admMd:'',mods:[],link:null,pin:false,login:true,aud:'all',status:'Черновик',off:false};
  const nm=new Set(n.mods||[]);
  const links=[['','— нет'],...KB_ARTS.filter(a=>a.active!==false).map(a=>['art:'+a.id,'Статья · '+a.t]),...[...BIZ,...ADM].filter((m,j,a)=>a.findIndex(x=>x.id===m.id)===j).map(m=>['mod:'+m.id,'Модуль · '+m.title]),...VIDEOS.filter(v=>!v.del).map(v=>['video:'+v.id,'Видео · '+v.t+(v.status==='Черновик'?' (черновик)':'')])];
  const tb=[['b','Жирный','Ж'],['h','Заголовок','H'],['ul','Список','list'],['a','Ссылка','link'],['img','Картинка','upload'],['vid','Видео','film']];
  openModal({form:true,size:'wide',render:()=>({title:isNew?'Новая новость':'Новость',sub:isNew?'Сначала сохраняется черновиком':esc(newsStTxt(n)),body:`<div class="form">
    ${fld('Заголовок',inp('nw-t',n.t),{req:true,full:true,id:'nw-t'})}
    ${fld('Тип',sel('nw-ty',Object.keys(NEWS_T).map(x=>[x,x]),n.type),{req:true,id:'nw-ty'})}${fld('Версия',inp('nw-v',n.ver,'placeholder="например, 1.4"'),{id:'nw-v',hint:'Необязательно у объявлений'})}
    ${fld('Дата публикации',inp('nw-d',n.date,'type="date"'),{req:true,id:'nw-d',hint:'Будущая дата — новость появится сама в этот день в 09:00 по Бишкеку'})}${fld('Для кого',sel('nw-aud',[['all','Все пользователи'],['adm','Только режим Админка']],n.aud),{id:'nw-aud'})}
    ${fld('Ссылка «Подробнее»',sel('nw-l',links,n.link?n.link.k+':'+n.link.id:''),{id:'nw-l',hint:'Статья, модуль или видео, необязательно; у видео — кнопка «▶ Смотреть видео»'})}${fld('Закрепить вверху',`<label class="row" style="gap:8px"><input type="checkbox" class="sw" id="nw-pin" ${n.pin?'checked':''}>новость показывается над лентой</label>`,{id:'nw-pin'})}
    ${fld('Показывать при входе',`<label class="row" style="gap:8px"><input type="checkbox" class="sw" id="nw-login" ${n.login!==false?'checked':''}>в окне «Что нового», пока пользователь её не прочитал</label>`,{id:'nw-login',full:true})}
    ${fld('Модули',`<div class="chipsel" id="nw-mods" role="group" aria-label="Модули">${NEWS_MODS().map(([k,t])=>`<button type="button" data-nwmod="${k}" class="${nm.has(k)?'on':''}" aria-pressed="${nm.has(k)}">${nm.has(k)?ic('check','sm'):''}${esc(t)}</button>`).join('')}</div>`,{full:true,id:'nw-mods',hint:'Новость про модуль видят только те, у кого он есть (право и учётная политика); без модулей — все'})}
    ${fld('Краткое описание',inp('nw-s',n.short||'','maxlength="200" placeholder="Одна-две строки для ленты"'),{req:true,full:true,id:'nw-s',hint:'Показывается в ленте «Новостей»; до 200 знаков'})}</div>
    <div class="fld full"><label class="lbl" for="nw-md">Подробное описание (markdown)</label>
    <div class="seg nw-adm-sw" role="group" aria-label="Какой текст"><button type="button" data-nwtx="u" class="on" aria-pressed="true">Для пользователей</button><button type="button" data-nwtx="a" aria-pressed="false">Для администратора платформы</button></div>
    <div class="md-edit"><div class="md-bar row">${tb.map(([k,t,i])=>`<button type="button" class="btn sm" data-md="${k}" title="${t}" aria-label="${t}">${i.length<3?`<b>${i}</b>`:ic(i,'sm')}<span class="md-bl">${t}</span></button>`).join('')}<input type="file" id="nw-img" accept="image/*" hidden><div class="grow"></div>
      <div class="seg md-sw" role="group" aria-label="Текст или предпросмотр"><button type="button" data-mdv="text" class="on">Текст</button><button type="button" data-mdv="prev">Предпросмотр</button></div></div>
      <div class="md-split" data-v="text"><textarea class="inp md-src" id="nw-md" spellcheck="true" aria-label="Текст для пользователей">${esc(n.md||'')}</textarea><textarea class="inp md-src md-off" id="nw-adm" spellcheck="true" aria-label="Текст для администратора платформы" placeholder="Что изменилось в Админке, технические подробности: видно только в режиме Админка">${esc(n.admMd||'')}</textarea><div class="md-prev kb-art md" id="nw-pv" aria-label="Предпросмотр"></div></div>
      <div class="hint">Разделы: «Что нового», «Изменено», «Исправлено», «Где найти», «Что нужно сделать»; пустые разделы не показываются. Можно: # и ## заголовки, **жирный**, *курсив*, списки «- » и «1. », [ссылка](https://…), ссылка на модуль [Перейти](#mod:reports), на его вкладку (#mod:dicts.types), статью (#art:a5) или видео (кнопка «Видео»: у пользователя — «▶ название · 3:25»), картинка, «> » примечание, «---» разделитель, таблица | a | b |. HTML не выполняется.</div>
      <div class="hint">Для пользователей — что изменилось для них и где это найти, без слов «прототип», «миграция», «стенд», «поток», «PR», «справочник платформы». Всё про Админку и технические подробности — в тексте «Для администратора платформы»: его видят только в режиме Админка, под чертой с этой подписью.</div><div class="nw-warn" id="nw-warn" aria-live="polite"></div><div class="err" id="nw-md-err"></div></div>`,
    foot:`<button class="btn ghost" data-close>Отмена</button><div class="grow"></div>${n.status==='Черновик'?`<button class="btn" id="nw-save">Сохранить черновик</button><button class="btn cta" id="nw-pub">${ic('send','sm')}Опубликовать</button>`:`<button class="btn cta" id="nw-save">Сохранить</button>`}`,
    mount(el,m){const tu=$('#nw-md',el),tad=$('#nw-adm',el),pv=$('#nw-pv',el),split=$('.md-split',el);let ta=tu;
      // Предупреждение о технических словах в тексте для пользователей (не мешает сохранить)
      const warn=()=>{const w=newsTechWords(tu.value);$('#nw-warn',el).textContent=w.length?`В тексте для пользователей: ${w.map(x=>'«'+x+'»').join(', ')}. Такое — в текст «Для администратора платформы».`:''};
      const draw=()=>{pv.innerHTML=mdHtml(mdTrim(ta.value))||'<span class="muted">Пусто</span>';if(ta===tu)warn()};draw();warn();tu.oninput=draw;tad.oninput=draw;
      // Второй текст пишется в том же редакторе: панель кнопок и предпросмотр работают с выбранным текстом
      $$('[data-nwtx]',el).forEach(b=>b.onclick=()=>{ta=b.dataset.nwtx==='a'?tad:tu;tu.classList.toggle('md-off',ta!==tu);tad.classList.toggle('md-off',ta!==tad);$$('[data-nwtx]',el).forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',String(x===b))});draw()});
      $('#nw-mods',el).onclick=e=>{const b=e.target.closest('[data-nwmod]');if(!b)return;const k=b.dataset.nwmod,on=!nm.has(k);if(on)nm.add(k);else nm.delete(k);b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on));b.innerHTML=(on?ic('check','sm'):'')+esc(newsModName(k))};
      $$('[data-mdv]',el).forEach(b=>b.onclick=()=>{split.dataset.v=b.dataset.mdv;$$('[data-mdv]',el).forEach(x=>x.classList.toggle('on',x===b));draw()});
      const wrap=(pre,post,ph)=>{const a=ta.selectionStart,z=ta.selectionEnd,sel=ta.value.slice(a,z)||ph;ta.setRangeText(pre+sel+post,a,z,'end');ta.focus();if(sel===ph)ta.setSelectionRange(a+pre.length,a+pre.length+ph.length);draw()};
      const line=pre=>{const a=ta.selectionStart;const ls=ta.value.lastIndexOf('\n',a-1)+1;ta.setRangeText(pre,ls,ls,'end');ta.focus();draw()};
      $$('[data-md]',el).forEach(b=>b.onclick=()=>{const k=b.dataset.md;if(k==='b')wrap('**','**','жирный текст');if(k==='h')line('## ');if(k==='ul')line('- ');if(k==='a')wrap('[','](https://)','текст ссылки');if(k==='img')$('#nw-img',el).click();if(k==='vid')vidPickMenu(b,v=>{ta.setRangeText(`[▶ ${v.t.replace(/[\[\]]/g,'')}](#video:${v.id})`,ta.selectionStart,ta.selectionEnd,'end');ta.focus();draw()})});
      $('#nw-img',el).onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024)return toast('Картинка больше 2 МБ','alert',true);const rd=new FileReader();rd.onload=()=>{ta.setRangeText(`\n![${f.name.replace(/[\[\]]/g,'')}](${rd.result})\n`,ta.selectionStart,ta.selectionEnd,'end');draw();toast('Картинка добавлена в текст')};rd.readAsDataURL(f)};
      $('#nw-ty',el).onchange=()=>{$('#nw-login',el).checked=newsLoginDef({type:val(el,'nw-ty'),pin:$('#nw-pin',el).checked})};
      const read=()=>{const lv=val(el,'nw-l');return {t:val(el,'nw-t'),type:val(el,'nw-ty'),ver:val(el,'nw-v').trim(),date:val(el,'nw-d'),aud:val(el,'nw-aud'),pin:$('#nw-pin',el).checked,login:$('#nw-login',el).checked,short:val(el,'nw-s').trim(),md:mdTrim(tu.value),admMd:mdTrim(tad.value),mods:NEWS_MODS().map(x=>x[0]).filter(k=>nm.has(k)),link:lv?{k:lv.split(':')[0],id:lv.split(':')[1]}:null}};
      // Без текста для пользователей можно только новость «Только режим Админка» со вторым текстом
      const save=pub=>{const v=read();const mdOk=!!mdText(v.md)||v.aud==='adm'&&!!mdText(v.admMd);$('#nw-md-err',el).textContent=mdOk?'':'Введите подробное описание';tu.classList.toggle('bad',!mdOk);
        const ok=[setErr(el,'nw-t',v.t?'':'Введите заголовок'),setErr(el,'nw-d',/^\d{4}-\d\d-\d\d$/.test(v.date)?'':'Укажите дату'),setErr(el,'nw-s',v.short?'':'Введите краткое описание для ленты'),mdOk,setErr(el,'nw-v',v.ver||v.type==='Объявление'||!pub&&n.status==='Черновик'?'':'Укажите версию: без неё можно только объявление')].every(Boolean);if(!ok)return;
        if(isNew){const o=born(Object.assign({id:'n'+Date.now().toString(36),status:'Черновик',off:false,hist:[]},v));NEWS.push(o);newsLog(o,'Черновик');if(pub){o.status='Опубликовано';newsLog(o,'Опубликовано')}}
        else{const was=n.status;Object.assign(n,v);touch(n);if(was==='Опубликовано'){n.edited=TODAY;pdLog(`Новости: «${n.t}» исправлена`,'news')}else if(pub){n.status='Опубликовано';newsLog(n,'Опубликовано')}else pdLog(`Новости: черновик «${n.t}» сохранён`,'news')}
        m.close();refreshAll();const o=isNew?NEWS[NEWS.length-1]:n;toast(o.status==='Черновик'?'Черновик сохранён: его видит только администратор платформы':newsLive(o)?'Новость опубликована: у всех на вкладке «Новости» с отметкой «Новое»':`Новость появится ${fmtD(o.date)} в 09:00`)};
      const s=$('#nw-save',el);s.onclick=()=>save(false);const p=$('#nw-pub',el);if(p)p.onclick=()=>save(true)}})})}
function newsActs(n){return [{label:'Изменить',icon:'edit',run:()=>newsEditDlg(n)},{label:'Предпросмотр',icon:'eye',run:()=>openModal({size:'wide',render:()=>({title:esc(n.t),sub:fmtD(n.date),body:`${newsPill(n.type)}<p class="muted">${esc(newsShort(n))}</p><div class="kb-art md">${mdHtml(n.md)}</div>${newsAdmHtml(n)}`,foot:'<div class="grow"></div><button class="btn cta" data-close>Закрыть</button>'})})},{label:'Отправить в Telegram',icon:'tg',sub:'Откроет «Рассылку» с полями из новости',disabled:!newsLive(n)||n.aud==='adm',reason:n.aud==='adm'?'Рассылка — только для новостей «Все пользователи»':n.status==='Опубликовано'&&!n.off?'Новость ещё не вышла: рассылку можно отправить, когда она появится у пользователей':'Сначала опубликуйте новость',run:()=>{tgCastFromNews(n);go('tg','cast');toast('Поля рассылки заполнены из новости','tg')}},{sep:true},
  n.status==='Черновик'?{label:'Опубликовать',icon:'send',run:()=>{n.status='Опубликовано';touch(n);newsLog(n,'Опубликовано');refreshAll();toast(newsLive(n)?'Новость опубликована':`Новость появится ${fmtD(n.date)} в 09:00`)}}:
  n.off?{label:'Вернуть в публикацию',icon:'refresh',run:()=>{n.off=false;touch(n);newsLog(n,'Возвращена в публикацию');refreshAll()}}:{label:'Снять с публикации',icon:'ban',sub:'Пропадёт у пользователей, останется здесь',run:()=>confirmDlg({title:`Снять «${esc(n.t)}» с публикации?`,text:'Новость пропадёт из вкладки «Новости» у всех пользователей. Вернуть её можно в любой момент.',ok:'Снять с публикации',danger:true,run:()=>{n.off=true;touch(n);newsLog(n,'Снято с публикации');refreshAll();toast('Новость снята с публикации')}})},
  {label:'Удалить',icon:'trash',danger:true,disabled:n.status!=='Черновик',reason:'Удалить можно только черновик; опубликованную — снять с публикации',run:()=>confirmDlg({title:`Удалить черновик «${esc(n.t)}»?`,text:'Черновик никто, кроме администраторов, не видел.',ok:'Удалить',danger:true,run:()=>{NEWS.splice(NEWS.indexOf(n),1);pdLog(`Новости: черновик «${n.t}» удалён`,'news');refreshAll();toast('Черновик удалён')}})}]}
function renderNewsAdm(body,fresh,ioBar){body.innerHTML=`<div class="note">${ic('info')}<span>Новости видят все пользователи всех организаций во вкладке «Новости» модуля «База знаний»; новость с модулями — только те, у кого есть хотя бы один из них. Текст «Для администратора платформы» виден только в режиме Админка. При входе новости с отметкой «Показывать при входе» открываются в окне «Что нового». В Telegram новость сама не уходит: рассылку запускает администратор — меню строки → «Отправить в Telegram». Черновик видит только администратор платформы; будущая дата публикации — новость появится сама в 09:00 по Бишкеку.</span></div>${ioBar('kbnews')}<div id="pg"></div>${pdHistHtml('news')}`;
  grid($('#pg',body),{id:'kb-news',cols:[{key:'id',label:'Код',type:'text',w:90,val:n=>n.id,cls:'mono',hide:true},{key:'date',label:'Дата публикации',type:'date',w:140,val:n=>n.date},{key:'ver',label:'Версия',type:'enum',w:100,val:n=>n.ver||'—'},{key:'type',label:'Тип',type:'enum',w:150,val:n=>n.type,html:n=>newsPill(n.type)},
    {key:'t',label:'Заголовок',type:'text',w:330,val:n=>n.t,html:n=>`${n.pin?ic('star','sm')+' ':''}<span class="strong">${esc(n.t)}</span>`},{key:'status',label:'Статус',type:'enum',w:230,val:newsStTxt,html:n=>`<span class="pill sm ${n.status==='Черновик'?'faint':n.off?'red':newsLive(n)?'green':'yellow'}">${esc(newsStTxt(n))}</span>`},
    {key:'aud',label:'Для кого',type:'enum',w:170,val:n=>n.aud==='adm'?'Только режим Админка':'Все пользователи'},{key:'mods',label:'Модули',type:'text',w:200,val:n=>(n.mods||[]).map(newsModName).join(', ')||'—'},{key:'adm',label:'Для администратора платформы',type:'enum',w:150,hide:true,val:n=>n.admMd&&mdText(n.admMd)?'Есть':'Нет'},{key:'pin',label:'Закреплено',type:'enum',w:110,hide:true,val:n=>n.pin?'Да':'Нет'},{key:'edited',label:'Изменено',type:'date',w:120,hide:true,val:n=>n.edited||''},{key:'read',label:'Прочитали',type:'int',w:110,num:true,hide:true,val:n=>Object.values(NEWS_READ).filter(s=>s.has(n.id)).length}],
    rows:()=>NEWS,title:'t',noun:['новость','новости','новостей'],sort:{key:'date',dir:-1},rowClass:n=>n.status==='Черновик'||n.off?'muted':'',open:n=>newsEditDlg(n),actions:newsActs,simulateLoad:fresh})}

